PREFIX moose: <https://moosedev.dev/kg/ontology/software-architecture/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?iri ?title WHERE {
  ?iri a moose:ArchitecturalDecision ;
       rdfs:label ?title ;
       moose:status "proposed" .
}
ORDER BY ?title

